"use strict";(globalThis.webpackChunkdocusaurus_text_book=globalThis.webpackChunkdocusaurus_text_book||[]).push([[9575],{9881:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/intro","label":"Introduction: The Dawn of Embodied Intelligence","docId":"intro","unlisted":false},{"type":"category","label":"Chapter 1: The Robotic Nervous System","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter1/ros2-introduction","label":"Module 1: The Robotic Nervous System (ROS 2)","docId":"chapter1/ros2-introduction","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter1/python-agents-and-ros","label":"Module 2: Python Agents and ROS","docId":"chapter1/python-agents-and-ros","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter1/describing-your-robot-urdf","label":"Module 3: Describing Your Robot (URDF)","docId":"chapter1/describing-your-robot-urdf","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Chapter 2: The Digital Twin","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter2/physics-simulation","label":"Module 1: The Digital Twin (Gazebo)","docId":"chapter2/physics-simulation","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter2/human-robot-interaction","label":"Module 2: Human-Robot Interaction in Simulation","docId":"chapter2/human-robot-interaction","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter2/sensors","label":"Module 3: Virtual Sensors (LiDAR, Cameras, IMU)","docId":"chapter2/sensors","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Chapter 3: The AI-Robot Brain","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter3/photorealistic-simulation","label":"Module 1: The AI-Robot Brain (NVIDIA Isaac)","docId":"chapter3/photorealistic-simulation","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter3/synthetic-data","label":"Module 2: Synthetic Data Generation (SDG)","docId":"chapter3/synthetic-data","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter3/isaac-ros-vslam","label":"Module 3: Isaac ROS VSLAM","docId":"chapter3/isaac-ros-vslam","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter3/nav2-planning","label":"Module 4: Nav2 Planning for Humanoids","docId":"chapter3/nav2-planning","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Chapter 4: Vision-Language-Action","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter4/voice-to-action","label":"Module 1: Vision-Language-Action (VLA)","docId":"chapter4/voice-to-action","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter4/llm-cognitive-planning","label":"Module 2: LLM-Powered Cognitive Planning","docId":"chapter4/llm-cognitive-planning","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/chapter4/capstone-autonomous-humanoid","label":"Module 3: Capstone - The Autonomous Humanoid","docId":"chapter4/capstone-autonomous-humanoid","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"chapter1/describing-your-robot-urdf":{"id":"chapter1/describing-your-robot-urdf","title":"Module 3: Describing Your Robot (URDF)","description":"So far, we have built a nervous system (ROS 2) and a brain (Python Agents). But for any of this to be meaningful, ROS needs to understand the physical structure of the robot it\'s controlling. What does the robot look like? Where are its joints? How do they move?","sidebar":"tutorialSidebar"},"chapter1/python-agents-and-ros":{"id":"chapter1/python-agents-and-ros","title":"Module 2: Python Agents and ROS","description":"In the previous module, we learned about the fundamental building blocks of ROS 2: Nodes, Topics, and Services. Now, we\'ll elevate our approach by thinking about nodes not just as simple programs, but as intelligent Agents.","sidebar":"tutorialSidebar"},"chapter1/ros2-introduction":{"id":"chapter1/ros2-introduction","title":"Module 1: The Robotic Nervous System (ROS 2)","description":"Welcome to the foundational module of our journey into Physical AI and Humanoid Robotics. Before we can make a robot see, think, or act, we must first build its nervous system. In modern robotics, this nervous system is the Robot Operating System (ROS), specifically its second iteration, ROS 2.","sidebar":"tutorialSidebar"},"chapter2/human-robot-interaction":{"id":"chapter2/human-robot-interaction","title":"Module 2: Human-Robot Interaction in Simulation","description":"A humanoid robot, by its very nature, is designed to operate in human-centric environments. This means it must be able to perceive, understand, and safely interact with people. Developing and testing these capabilities on a physical robot is dangerous and impractical. The digital twin is therefore an essential tool for Human-Robot Interaction (HRI) research and development.","sidebar":"tutorialSidebar"},"chapter2/physics-simulation":{"id":"chapter2/physics-simulation","title":"Module 1: The Digital Twin (Gazebo)","description":"A Digital Twin is a virtual, dynamic model of a physical object or system. In robotics, it\'s our laboratory\u2014a place where we can design, test, and break our robots with zero physical cost or risk. A high-fidelity digital twin allows us to develop and validate 99% of our AI and control software before ever deploying it to a real, expensive humanoid.","sidebar":"tutorialSidebar"},"chapter2/sensors":{"id":"chapter2/sensors","title":"Module 3: Virtual Sensors (LiDAR, Cameras, IMU)","description":"An agent can only be as good as its perception. To operate in the world, a robot needs to sense its environment. In our digital twin, we must equip our simulated robot with a suite of virtual sensors that mimic their real-world counterparts.","sidebar":"tutorialSidebar"},"chapter3/isaac-ros-vslam":{"id":"chapter3/isaac-ros-vslam","title":"Module 3: Isaac ROS VSLAM","description":"Once a robot is placed in an unknown environment, it faces two fundamental questions: \\"Where am I?\\" and \\"What does this place look like?\\" The process of answering both questions simultaneously is called SLAM (Simultaneous Localization and Mapping).","sidebar":"tutorialSidebar"},"chapter3/nav2-planning":{"id":"chapter3/nav2-planning","title":"Module 4: Nav2 Planning for Humanoids","description":"We\'ve given our robot a digital twin, a powerful vision system, and a VSLAM algorithm to tell it where it is. Now, we need to give it a \\"brain\\" for navigation. How does it get from point A to point B safely and efficiently?","sidebar":"tutorialSidebar"},"chapter3/photorealistic-simulation":{"id":"chapter3/photorealistic-simulation","title":"Module 1: The AI-Robot Brain (NVIDIA Isaac)","description":"While Gazebo is a fantastic tool for physics and dynamics simulation, the future of robot AI is increasingly reliant on vision. To train robust, deep learning-based perception models, we need more than just physically plausible worlds; we need photorealistic worlds. This is where the NVIDIA Isaac platform shines.","sidebar":"tutorialSidebar"},"chapter3/synthetic-data":{"id":"chapter3/synthetic-data","title":"Module 2: Synthetic Data Generation (SDG)","description":"One of the biggest bottlenecks in modern AI is the need for massive amounts of high-quality, labeled data. For a humanoid robot, this is even more critical. How do you get 100,000 images of a specific object, from every possible angle, in every possible lighting condition, with a perfect segmentation mask and bounding box for each? You can\'t do it with real cameras.","sidebar":"tutorialSidebar"},"chapter4/capstone-autonomous-humanoid":{"id":"chapter4/capstone-autonomous-humanoid","title":"Module 3: Capstone - The Autonomous Humanoid","description":"We have reached the summit. We have assembled all the individual components of a modern Physical AI system. Now, it\'s time to put them all together in a capstone project that demonstrates true autonomous behavior.","sidebar":"tutorialSidebar"},"chapter4/llm-cognitive-planning":{"id":"chapter4/llm-cognitive-planning","title":"Module 2: LLM-Powered Cognitive Planning","description":"We\'ve successfully converted a user\'s spoken words into a structured command like {\\"intent\\" \\"red apple\\"}. Now comes the most challenging part: how does the robot figure out the sequence of steps required to fulfill this command?","sidebar":"tutorialSidebar"},"chapter4/voice-to-action":{"id":"chapter4/voice-to-action","title":"Module 1: Vision-Language-Action (VLA)","description":"Welcome to the final and most exciting chapter. So far, we\'ve built the robot\'s body (URDF), its nervous system (ROS 2), its virtual playground (Simulators), and its spatial intelligence (SLAM & Nav2). Now, it\'s time to give it a human-like interface. It\'s time to talk to our robot.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Introduction: The Dawn of Embodied Intelligence","description":"Welcome to \\"Physical AI & Humanoid Robotics,\\" an interactive textbook designed to guide you through the fascinating world where artificial intelligence meets the physical realm. This book delves deep into the principles and practices of building intelligent robotic systems, exploring the fusion of advanced AI with embodied intelligence. We aim to equip you with the knowledge and tools necessary to create robots that can perceive, reason, and act effectively in complex, unstructured environments.","sidebar":"tutorialSidebar"},"tutorial-basics/congratulations":{"id":"tutorial-basics/congratulations","title":"Congratulations!","description":"You have just learned the basics of Docusaurus and made some changes to the initial template."},"tutorial-basics/create-a-blog-post":{"id":"tutorial-basics/create-a-blog-post","title":"Create a Blog Post","description":"Docusaurus creates a page for each blog post, but also a blog index page, a tag system, an RSS feed..."},"tutorial-basics/create-a-document":{"id":"tutorial-basics/create-a-document","title":"Create a Document","description":"Documents are groups of pages connected through:"},"tutorial-basics/create-a-page":{"id":"tutorial-basics/create-a-page","title":"Create a Page","description":"Add Markdown or React files to src/pages to create a standalone page:"},"tutorial-basics/deploy-your-site":{"id":"tutorial-basics/deploy-your-site","title":"Deploy your site","description":"Docusaurus is a static-site-generator (also called Jamstack)."},"tutorial-basics/markdown-features":{"id":"tutorial-basics/markdown-features","title":"Markdown Features","description":"Docusaurus supports Markdown and a few additional features."},"tutorial-extras/manage-docs-versions":{"id":"tutorial-extras/manage-docs-versions","title":"Manage Docs Versions","description":"Docusaurus can manage multiple versions of your docs."},"tutorial-extras/translate-your-site":{"id":"tutorial-extras/translate-your-site","title":"Translate your site","description":"Let\'s translate docs/intro.md to French."}}}}')}}]);